@font-face{font-family:FikrArabic;src:url('../fonts/IBMPlexSansArabic-SemiBold.woff2') format('woff2');font-weight:600;font-display:swap}
@font-face{font-family:FikrArabic;src:url('../fonts/IBMPlexSansArabic-Bold.woff2') format('woff2');font-weight:700;font-display:swap}
:root{color-scheme:light;--fikr-bg:#f6f4dd;--fikr-text:#2b2332;--fikr-muted:#5c534e;--fikr-purple:#6b4c75;--fikr-lilac:#dbd9df;--fikr-olive:#c4c60b;--fikr-line:#b9afad;--fikr-panel:#dbd9df;--fikr-dark:#2b2332}
html[data-theme=dark]{color-scheme:dark;--fikr-bg:#2b2332;--fikr-text:#f6f4dd;--fikr-muted:#dbd9df;--fikr-lilac:#6b4c75;--fikr-line:#88768e;--fikr-panel:#5d4770}
*{box-sizing:border-box}html{scroll-padding-top:112px}body{margin:0;background:var(--fikr-bg);color:var(--fikr-text);font-family:FikrArabic,'IBM Plex Sans Arabic',Tahoma,sans-serif;line-height:1.7}a{color:inherit}button,input,select{font:inherit}button,a{-webkit-tap-highlight-color:transparent}a:focus-visible,button:focus-visible{outline:3px solid var(--fikr-purple);outline-offset:5px}h1,h2,h3,p{margin:0}img,svg{max-width:100%}.skip-link{position:fixed;top:8px;right:8px;padding:12px;background:var(--fikr-text);color:var(--fikr-bg);z-index:1000;transform:translateY(-150%)}.skip-link:focus{transform:none}.fikr-shell{width:min(1248px,calc(100% - 64px));margin-inline:auto}
.fikr-nav{height:96px;padding-inline:max(32px,calc((100% - 1248px)/2));display:flex;align-items:center;gap:28px;background:var(--fikr-bg);position:sticky;top:0;z-index:50;border-bottom:1px solid color-mix(in srgb,var(--fikr-line) 30%,transparent)}.fikr-nav nav{display:flex;justify-content:center;gap:32px;flex:1}.fikr-nav a{text-decoration:none;font-size:14px}.fikr-nav__back{white-space:nowrap;direction:ltr}.fikr-nav__brand{display:grid;place-items:center;width:64px;height:56px;background:var(--fikr-dark)}.fikr-mark{font-size:48px;line-height:1;font-weight:700;color:var(--fikr-olive)}.fikr-theme{border:0;background:transparent;color:var(--fikr-text);font-size:28px;width:44px;height:44px;cursor:pointer;flex-shrink:0}.sanad-header--scrolled{box-shadow:0 4px 24px #00000012;backdrop-filter:blur(16px)}
.fikr-hero{padding-block:80px 56px;min-height:784px}.fikr-hero__inner{width:min(1248px,calc(100% - 64px));margin-inline:auto;display:grid;grid-template-columns:688fr 528fr;gap:60px;align-items:start}.fikr-hero__copy{display:flex;align-items:flex-start;flex-direction:column;gap:24px}.fikr-kicker{color:var(--fikr-purple);font-size:16px}.fikr-hero__title{font-weight:700;font-size:48px;line-height:1.42;max-width:688px}.fikr-hero__desc{font-size:20px;line-height:1.6;color:var(--fikr-muted)}.fikr-button{display:inline-flex;align-items:center;justify-content:center;padding:16px 32px;min-height:64px;background:var(--fikr-purple);color:#f6f4dd;border:0;border-radius:40px;font-size:16px;font-weight:600;text-decoration:none;text-align:center}.fikr-hero__tags{font-size:14px;color:var(--fikr-muted)}.fikr-hero__visual{height:528px;position:relative;isolation:isolate;overflow:hidden;display:grid;place-items:center}.fikr-mark--hero{font-size:280px;color:var(--fikr-text)}.fikr-original-logo{position:absolute;inset:0;background-size:contain;background-position:center;background-repeat:no-repeat}.fikr-orbit{position:absolute;width:86%;height:86%;border:1px solid var(--fikr-line);border-radius:50%;opacity:.2;z-index:-1}.fikr-orbit--small{width:54%;height:54%}html[data-theme=dark] .fikr-original-logo{filter:brightness(0) saturate(100%) invert(95%) sepia(11%) saturate(453%) hue-rotate(8deg)}.fikr-original-logo~*{display:none}.fikr-mark--hero:has(+.fikr-original-logo){visibility:hidden}
.fikr-expertise{height:64px;background:var(--fikr-olive);color:#2b2332;overflow:hidden;display:flex;align-items:center;margin-block:16px 32px;direction:ltr}.fikr-marquee-track{display:flex;flex:none;width:max-content;will-change:transform}.fikr-marquee-track>span{white-space:nowrap;direction:rtl;font-size:16px;display:block;flex-shrink:0}
.fikr-section{padding-block:72px}.fikr-section h2{font-size:40px;font-weight:600;line-height:1.5}.fikr-section p{color:var(--fikr-muted);font-size:18px}.fikr-philosophy{min-height:640px;display:grid;grid-template-columns:640fr 512fr;gap:96px;align-items:start;padding-top:88px}.fikr-philosophy__text{margin-top:28px}.fikr-philosophy__text p{font-size:20px;line-height:1.8;margin-bottom:24px}.fikr-illustration{height:400px;background-repeat:no-repeat;background-position:center;background-size:contain}.fikr-services-section{min-height:1176px;padding-block:48px 88px}.fikr-section__heading{position:relative;margin-bottom:64px}.fikr-section__heading>span{position:absolute;left:0;top:0;color:var(--fikr-purple);font-size:16px}.fikr-section__heading p{margin-top:6px}.fikr-services{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.fkr-discipline{padding:32px;min-height:872px;border-radius:16px}.fikr-card--featured{background:var(--fikr-panel)}.fikr-service-art{width:225px;max-width:100%;height:225px;background-size:contain;background-position:center;background-repeat:no-repeat;margin-bottom:8px}.fkr-discipline>b{display:block;color:var(--fikr-purple);font-size:24px;font-weight:600}.divider{display:block;height:1px;background:var(--fikr-purple);margin:12px 0 24px}.fkr-discipline h3{font-size:22px;line-height:1.5;font-weight:600}.fkr-discipline small{display:block;font-size:14px;margin-top:8px;text-align:right}.fkr-discipline ul{padding-inline-start:18px;margin:24px 0 0;color:var(--fikr-muted);font-size:17px;line-height:1.8}.fkr-discipline li{margin-bottom:20px}.fkr-discipline li::marker{color:var(--fikr-purple)}
.fikr-industries{background:var(--fikr-lilac);margin-block:32px;min-height:1392px}.fikr-industries>.fikr-shell>p{margin-top:12px}.fikr-industry-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:56px 64px;margin-top:64px;padding-bottom:80px}.fikr-industry-grid>article{min-height:472px;background:var(--fikr-bg);border-radius:16px;overflow:hidden}.fikr-industry-grid>article:nth-child(even){transform:translateY(80px)}.fikr-photo{height:272px;overflow:hidden}.portrait-img{height:125%;position:relative;top:-12.5%;background-size:cover;background-position:center}.fikr-industry-copy{padding:24px 32px 32px}.fikr-industry-copy h3{font-size:22px;line-height:1.5}.fikr-industry-copy p{font-size:17px;margin-top:8px}.fikr-industry-copy small{font-size:14px;display:block;margin-top:8px}
.fikr-method{position:relative;min-height:1016px;padding-top:80px;isolation:isolate}.growth-loop{position:absolute;top:210px;inset-inline:0;width:100%;height:660px;color:var(--fikr-purple);opacity:.35;z-index:-1}.fikr-stages{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px;margin-top:76px;padding-inline:24px}.method-step{min-height:360px;padding:24px;border:1px solid var(--fikr-line);border-radius:16px;background:var(--fikr-bg);position:relative}.method-step:nth-child(even){background:var(--fikr-panel)}.method-step:nth-child(2){top:104px}.method-step:nth-child(3){top:208px}.method-step:nth-child(4){top:312px}.method-step>b{display:block;font-size:40px;font-weight:600;color:var(--fikr-purple);margin-bottom:32px}.method-step h3{font-size:21px;font-weight:600;line-height:1.5}.method-step small{font-size:13px;display:block;margin-top:6px}.method-step p{font-size:17px;margin-top:20px}.method-step.is-active{border-color:var(--fikr-purple);box-shadow:0 0 0 1px var(--fikr-purple)}
.fikr-cta{margin-top:32px;min-height:560px;background:#2b2332;color:#f6f4dd}.fikr-cta__inner{display:grid;grid-template-columns:704fr 576fr;gap:32px;align-items:center}.fikr-cta h2{font-size:36px;line-height:1.5;font-weight:600}.fikr-cta p{font-size:18px;color:#dbd9df;margin:24px 0}.fikr-cta .fikr-button{background:#c4c60b;color:#2b2332}.fikr-cta__orbit{height:528px;background-size:contain;background-repeat:no-repeat;background-position:center}.fikr-footer{background:#2b2332;color:#f6f4dd;padding-block:56px 24px}.fikr-footer__grid{display:grid;grid-template-columns:1.5fr 1fr 1fr 1fr;gap:48px}.fikr-footer__grid>div,.fikr-footer nav{display:flex;flex-direction:column;align-items:flex-start;gap:10px}.fikr-footer h2{font-size:17px;font-weight:600;margin-bottom:8px}.fikr-footer a{font-size:14px;color:#dbd9df;text-decoration:none}.fikr-footer strong{font-size:16px;max-width:280px}.fikr-footer .fikr-mark{font-size:64px;margin-bottom:16px}.fikr-footer__legal{text-align:center;color:#dbd9df;font-size:13px;border-top:1px solid #6b4c7555;margin:40px auto 0;padding-top:24px}
.whatsapp-float{position:fixed;bottom:24px;left:24px;z-index:70;width:56px;height:56px;display:grid;place-items:center;border-radius:50%;background:#128c4a;color:white;box-shadow:0 4px 16px #0003}.whatsapp-float:focus-visible{outline-color:#c4c60b}html[data-theme=dark] .fikr-kicker,html[data-theme=dark] .fkr-discipline>b,html[data-theme=dark] .method-step>b,html[data-theme=dark] .fikr-section__heading>span{color:#c6abc9}
@media(max-width:1100px){.fikr-hero__title{font-size:40px}.fikr-hero__inner{gap:32px}.fikr-hero__visual{height:440px}.fikr-nav{gap:16px}.fikr-nav nav{gap:20px}.fikr-philosophy{gap:48px}.fkr-discipline{padding:24px}.fkr-discipline h3{font-size:20px}.fikr-stages{padding-inline:0;gap:16px}.method-step{padding:16px}.method-step h3{font-size:19px}}
@media(max-width:800px){html{scroll-padding-top:140px}.fikr-shell,.fikr-hero__inner{width:calc(100% - 40px)}.fikr-nav{height:auto;min-height:88px;flex-wrap:wrap;padding:12px 20px;gap:12px}.fikr-nav__back{flex:1}.fikr-nav nav{order:4;flex-basis:100%;gap:24px;justify-content:space-between;overflow-x:auto}.fikr-nav__brand{width:48px;height:44px}.fikr-nav nav a{white-space:nowrap}.fikr-hero{padding-block:48px;min-height:auto}.fikr-hero__inner{grid-template-columns:1fr;gap:40px}.fikr-hero__title{font-size:36px}.fikr-hero__visual{height:auto;aspect-ratio:1;max-width:528px;width:100%;margin-inline:auto}.fikr-hero__desc{font-size:18px}.fikr-section{padding-block:56px}.fikr-section h2{font-size:30px}.fikr-philosophy{grid-template-columns:1fr;gap:24px;min-height:auto}.fikr-philosophy__text p{font-size:18px}.fikr-illustration{height:300px;order:2}.fikr-section__heading{margin-bottom:32px}.fikr-section__heading>span{position:static;display:block;margin-bottom:16px}.fikr-services{grid-template-columns:1fr}.fkr-discipline{min-height:0;padding:24px}.fikr-service-art{margin-inline:auto}.fkr-discipline h3{font-size:23px}.fikr-industry-grid{gap:24px;margin-top:32px;padding:0}.fikr-industry-grid>article{min-height:0}.fikr-industry-grid>article:nth-child(even){transform:none}.fikr-photo{height:210px}.fikr-industry-copy{padding:20px}.fikr-industry-copy h3{font-size:20px}.fikr-industry-copy p{font-size:16px}.fikr-method{min-height:0;padding-bottom:64px}.fikr-stages{grid-template-columns:repeat(2,minmax(0,1fr));margin-top:36px;gap:16px}.method-step{min-height:320px}.method-step:nth-child(n){top:0}.method-step>b{margin-bottom:16px}.growth-loop{display:none}.fikr-cta__inner{grid-template-columns:1fr;gap:16px;padding-top:48px}.fikr-cta h2{font-size:30px}.fikr-cta__orbit{height:300px}.fikr-footer__grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:32px}.fikr-footer__legal{padding-inline:20px}.fikr-button{max-width:100%;font-size:15px}.whatsapp-float{left:16px;bottom:16px;width:50px;height:50px}}
@media(max-width:480px){.fikr-industry-grid{grid-template-columns:1fr}.fikr-stages{grid-template-columns:1fr}.method-step{min-height:0}.method-step small{font-size:14px}.fikr-hero__title{font-size:32px}.fikr-footer__grid{gap:32px 16px}.fikr-footer__grid>div:first-child{grid-column:1/-1}.fikr-photo{height:240px}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation:none!important;transition:none!important}.fikr-marquee-track{transform:none!important}}
